   272	/**
   273	 * @brief Configuration TX (DAC) for AUDCODEC and AUDPRC.
   274	 */
   275	static void config_tx(rt_uint32_t channels, rt_uint32_t sr, rt_uint32_t fmt)
   276	{
   277	#define     mixer_sel  0x5150
   278	    struct rt_audio_caps caps;
   279	    struct rt_audio_sr_convert cfg;
   280	    // uint8_t g_hardware_mix_enable = 1;
   281	    /* mix left & right channel to mono channel output, too big volume sometime */
   282	    int out_sel = 0x5050;
   283	    // if (caps.udata.config.channels == 2 && g_hardware_mix_enable)
   284	    // {
   285	    //     out_sel = 0x5010; //mix left & right to speaker.  speaker pcm = left pcm + right pcm
   286	    // }
   287	
   288	    /* AUCODEC : set output as "AUDPRC_TX_TO_CODEC" (codec/mem/i2s). */
   289	    rt_device_control(g_audcodec_dev, AUDIO_CTL_SETOUTPUT, (void *)AUDPRC_TX_TO_CODEC);
   290	    caps.main_type = AUDIO_TYPE_OUTPUT;
   291	    caps.sub_type = 1 << HAL_AUDCODEC_DAC_CH0;
   292	#if defined(BSP_USING_BOARD_SF32LB58_LCD_N16R64N4)
   293	    caps.sub_type |= (1 << HAL_AUDCODEC_DAC_CH1);
   294	#endif
   295	    caps.udata.config.channels   = channels; // L,R,L,R,L,R, ......
   296	    caps.udata.config.samplerate = sr;
   297	    caps.udata.config.samplefmt = fmt; //8 16 24 or 32
   298	    rt_kprintf("prc_codec : sub_type=%d channel %d, samplerate %d, bits %d", caps.sub_type, caps.udata.config.channels,
   299	               caps.udata.config.samplerate, caps.udata.config.samplefmt);
   300	    rt_device_control(g_audcodec_dev, AUDIO_CTL_CONFIGURE, &caps);
   301	
   302	    /* AUDPRC : set output as "AUDPRC_TX_TO_CODEC" (codec/mem/i2s). */
   303	    rt_device_control(g_audprc_dev, AUDIO_CTL_SETOUTPUT, (void *)AUDPRC_TX_TO_CODEC);
   304	    cfg.channel = channels;
   305	    cfg.source_sr = sr;
   306	    cfg.dest_sr = sr;
   307	    rt_kprintf("speaker OUTPUTSRC channel=%d in_rate=%d out_rate=%d", cfg.channel, cfg.source_sr, cfg.dest_sr);
   308	    rt_device_control(g_audprc_dev, AUDIO_CTL_OUTPUTSRC, (void *)(&cfg));
   309	
   310	    /* AUDPRC : SELECTOR */
   311	    rt_kprintf("speaker select=0x%x mixer=0x%x", out_sel, mixer_sel);
   312	    caps.main_type = AUDIO_TYPE_SELECTOR;
   313	    caps.sub_type = 0xFF;
   314	    caps.udata.value   = out_sel;
   315	    rt_device_control(g_audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
   316	
   317	    /* AUDPRC : MIXER */
   318	    caps.main_type = AUDIO_TYPE_MIXER;
   319	    caps.sub_type = 0xFF;
   320	    caps.udata.value   = out_sel;
   321	    rt_device_control(g_audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
   322	
   323	    /* data source format */
   324	    caps.main_type = AUDIO_TYPE_OUTPUT;
   325	    caps.sub_type = HAL_AUDPRC_TX_CH0;
   326	    caps.udata.config.channels   = channels;
   327	    caps.udata.config.samplerate = sr;
   328	    caps.udata.config.samplefmt = fmt;
   329	    rt_kprintf("tx[0]: sub_type %d, ch %d, samrate %d, bits %d\n",
   330	               caps.sub_type,
   331	               caps.udata.config.channels,
   332	               caps.udata.config.samplerate,
   333	               caps.udata.config.samplefmt);
   334	
   335	    rt_device_control(g_audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
   336	
   337	    /* Set volume */
   338	    int vol = -18;
   339	    rt_kprintf("init volume=%d", vol);
   340	    rt_device_control(g_audcodec_dev, AUDIO_CTL_SETVOLUME, (void *)vol);
   341	}
