    91	static int audio_play_tone(AUDCODEC_HandleTypeDef *codec)
    92	{
    93	    AUDCODEC_DACCfgTypeDef cfg = codec->Init.dac_cfg;
    94	    uint32_t total = AUDIO_RATE * AUDIO_TONE_SEC;
    95	    uint32_t sent = 0;
    96	    uint32_t spins = 0;
    97	    int ret;
    98	
    99	    ret = HAL_AUDCODEC_Config_TChanel(codec, 0, &cfg);
   100	    if (ret != HAL_OK)
   101	        return ret;
   102	    ret = HAL_AUDCODEC_Config_DACPath_Volume(codec, 0, 0);
   103	    if (ret != HAL_OK)
   104	        return ret;
   105	    ret = HAL_AUDCODEC_Config_DACPath(codec, 1);
   106	    if (ret != HAL_OK)
   107	        return ret;
   108	    ret = HAL_AUDCODEC_Config_Analog_DACPath(&g_dac_clock);
   109	    if (ret != HAL_OK)
   110	        return ret;
   111	
   112	    __HAL_AUDCODEC_DAC_ENABLE(codec);
   113	    audio_pa_set(1);
   114	    syslog(LOG_INFO, "[AudioTest] SPEAKER: 1 kHz tone for %d s; listen now\n",
   115	           AUDIO_TONE_SEC);
   116	
   117	    while (sent < total && spins < 500000)
   118	    {
   119	        uint32_t stat = codec->Instance->APB_STAT;
   120	        uint32_t count = (stat & AUDCODEC_APB_STAT_DAC_CH0_FIFO_CNT_Msk) >>
   121	                         AUDCODEC_APB_STAT_DAC_CH0_FIFO_CNT_Pos;
   122	
   123	        if (count < 8)
   124	        {
   125	            codec->Instance->DAC_CH0_ENTRY =
   126	                (uint32_t)(uint16_t)g_tone[sent % 32];
   127	            sent++;
   128	        }
   129	        else
   130	        {
   131	            usleep(10);
   132	        }
   133	        spins++;
   134	    }
   135	
   136	    usleep(30000);
   137	    audio_pa_set(0);
   138	    __HAL_AUDCODEC_DAC_DISABLE(codec);
   139	
   140	    syslog(LOG_INFO, "[AudioTest] SPEAKER: queued=%lu/%lu\n",
   141	           (unsigned long)sent, (unsigned long)total);
   142	    return sent == total ? HAL_OK : HAL_TIMEOUT;
   143	}
   144	
   145	static int audio_capture_mic(AUDCODEC_HandleTypeDef *codec)
   146	{
   147	    AUDCODEC_ADCCfgTypeDef cfg = codec->Init.adc_cfg;
   148	    uint32_t target = AUDIO_RATE * AUDIO_MIC_SEC;
   149	    uint32_t got = 0;
   150	    uint32_t spins = 0;
   151	    int32_t min = INT32_MAX;
   152	    int32_t max = INT32_MIN;
   153	    uint64_t abs_sum = 0;
   154	    int ret;
   155	
   156	    ret = HAL_AUDCODEC_Config_RChanel(codec, 0, &cfg);
   157	    if (ret != HAL_OK)
   158	        return ret;
   159	    ret = HAL_AUDCODEC_Config_ADCPath_Volume(codec, 0, 0);
   160	    if (ret != HAL_OK)
   161	        return ret;
   162	    HAL_AUDCODEC_Config_Analog_ADCPath(&g_adc_clock);
   163	    __HAL_AUDCODEC_ADC_ENABLE(codec);
   164	
   165	    syslog(LOG_INFO, "[AudioTest] MICROPHONE: speak/tap near the MEMS mic for %d s\n",
   166	           AUDIO_MIC_SEC);
   167	
   168	    while (got < target && spins < 350000)
   169	    {
   170	        uint32_t stat = codec->Instance->APB_STAT;
   171	        uint32_t count = (stat & AUDCODEC_APB_STAT_ADC_CH0_FIFO_CNT_Msk) >>
   172	                         AUDCODEC_APB_STAT_ADC_CH0_FIFO_CNT_Pos;
   173	
   174	        if (count != 0)
   175	        {
   176	            int32_t sample = (int16_t)(codec->Instance->ADC_CH0_ENTRY & 0xffff);
   177	            int32_t a = sample < 0 ? -sample : sample;
   178	
   179	            if (sample < min) min = sample;
   180	            if (sample > max) max = sample;
   181	            abs_sum += (uint32_t)a;
   182	            got++;
   183	        }
   184	        else
   185	        {
   186	            usleep(10);
   187	        }
   188	        spins++;
   189	    }
   190	
   191	    __HAL_AUDCODEC_ADC_DISABLE(codec);
   192	    if (got == 0)
   193	    {
   194	        syslog(LOG_ERR, "[AudioTest] MICROPHONE: no ADC samples\n");
   195	        return HAL_TIMEOUT;
   196	    }
   197	
   198	    syslog(LOG_INFO,
   199	           "[AudioTest] MICROPHONE: samples=%lu min=%ld max=%ld avg_abs=%lu\n",
   200	           (unsigned long)got, (long)min, (long)max,
   201	           (unsigned long)(abs_sum / got));
   202	    return got == target ? HAL_OK : HAL_TIMEOUT;
   203	}
