   205	int velawear_audio_hw_test(void)
   206	{
   207	    AUDCODEC_HandleTypeDef codec;
   208	    int speaker_ret;
   209	    int mic_ret;
   210	
   211	    syslog(LOG_INFO, "[AudioTest] opening SF32LB52 AUDCODEC at %d Hz\n",
   212	           AUDIO_RATE);
   213	    if (audio_codec_open(&codec) != HAL_OK)
   214	    {
   215	        syslog(LOG_ERR, "[AudioTest] codec init failed\n");
   216	        return -1;
   217	    }
   218	
   219	    speaker_ret = audio_play_tone(&codec);
   220	    mic_ret = audio_capture_mic(&codec);
   221	    audio_codec_close(&codec);
   222	
   223	    syslog(LOG_INFO, "[AudioTest] result speaker=%d microphone=%d\n",
   224	           speaker_ret, mic_ret);
   225	    return (speaker_ret == HAL_OK && mic_ret == HAL_OK) ? 0 : -1;
   226	}
