    26	
    27	__WEAK void BSP_PowerUpCustom(bool is_deep_sleep)
    28	{
    29	    /* Always power on MPI2 NOR flash */
    30	    BSP_GPIO_Set(MPI2_POWER_PIN, 1, 1);
    31	
    32	    if (is_deep_sleep)
    33	    {
    34	        /* VSYS */
    35	        BSP_GPIO_Set(38, 1, 1);
    36	
    37	        /* VSYS to VCC_3V3 */
    38	        BSP_GPIO_Set(26, 1, 1);
    39	
    40	        /* GS_3V3 */
    41	        BSP_GPIO_Set(30, 1, 1);
    42	        HAL_Delay_us(500);
    43	
    44	        /* Configure Charger (AW32001) via I2C2 */
    45	        I2C_HandleTypeDef i2c_Handle = {0};
    46	        HAL_RCC_EnableModule(RCC_MOD_I2C2);
    47	        i2c_Handle.Instance = I2C2;
    48	        i2c_Handle.Mode = HAL_I2C_MODE_MASTER;
    49	        i2c_Handle.Init.AddressingMode = I2C_ADDRESSINGMODE_7BIT;
    50	        i2c_Handle.Init.ClockSpeed = 400000;
    51	        i2c_Handle.Init.GeneralCallMode = I2C_GENERALCALL_DISABLE;
    52	        i2c_Handle.Init.OwnAddress1 = 0;
    53	
    54	        if (HAL_I2C_Init(&i2c_Handle) == HAL_OK)
    55	        {
    56	            __HAL_I2C_ENABLE(&i2c_Handle);
    57	            const uint8_t charger_addr = 0x49;
    58	            uint8_t data = 0;
    59	
    60	            /* CEB, address 0x01, bit3 */
    61	            if (HAL_I2C_Mem_Read(&i2c_Handle, charger_addr, 0x01,
    62	                                 I2C_MEMADD_SIZE_8BIT, &data, 1, 1000) == HAL_OK)
    63	            {
    64	                data &= ~(1 << 3);
    65	                HAL_I2C_Mem_Write(&i2c_Handle, charger_addr, 0x01,
    66	                                  I2C_MEMADD_SIZE_8BIT, &data, 1, 1000);
    67	            }
    68	
    69	            /* Disable watchdog, address 0x05, bit5-6 */
    70	            if (HAL_I2C_Mem_Read(&i2c_Handle, charger_addr, 0x05,
    71	                                 I2C_MEMADD_SIZE_8BIT, &data, 1, 1000) == HAL_OK)
    72	            {
    73	                data &= ~(3 << 5);
    74	                HAL_I2C_Mem_Write(&i2c_Handle, charger_addr, 0x05,
    75	                                  I2C_MEMADD_SIZE_8BIT, &data, 1, 1000);
    76	            }
    77	
    78	            __HAL_I2C_DISABLE(&i2c_Handle);
    79	        }
    80	    }
    81	}
